            transitionTimingFunction: ['ease', Ease.rise],
          },
        ]}>
        <Text style={styles.brand} accessibilityRole="header" numberOfLines={1} adjustsFontSizeToFit>
          afterdream
        </Text>
        <Text style={styles.tagline} numberOfLines={1}>
          what did you dream about?
