import { Modal, Pressable, StyleSheet, Text, View } from 'react-native';
import Animated, { useReducedMotion } from 'react-native-reanimated';
import { useSafeAreaInsets } from 'react-native-safe-area-context';
import Svg, { Defs, Ellipse, RadialGradient, Stop } from 'react-native-svg';

import { FeatureIcon } from '@/components/paywall/feature-icons';
import { animate, RISE } from '@/components/today/motion';
import { BrandColors, BrandFonts } from '@/constants/theme';
import { keepLabel, reminderBlurb, reminderTitle, trialMarks, type PaidFeature } from '@/utils/subscription';

type TrialReminderProps = {
  /** The feature they tapped, or null when nothing is being nudged. */
  feature: PaidFeature | null;
  daysLeft: number;
  /** "not now": through to the feature, quiet until tomorrow. */
  onContinue: () => void;
  /** "keep it": on to the full paywall. */
  onSubscribe: () => void;
};

/**
 * The nudge on the way into a paid feature during the free trial: a mark per day of the
 * week, what they're using, and one quiet line out. It never blocks — "not now" carries on
 * into the feature — and it only says this once a day per feature.
 *
 * Deliberately not a second paywall: no plans, no pricing table, nothing filled in except
 * the days they have left.
 */
export function TrialReminder({ feature, daysLeft, onContinue, onSubscribe }: TrialReminderProps) {
  const insets = useSafeAreaInsets();
  const reduceMotion = useReducedMotion();
  if (!feature) return null;

  return (
    <Modal visible transparent animationType="fade" onRequestClose={onContinue} statusBarTranslucent>
      <Pressable accessibilityRole="button" accessibilityLabel="Dismiss" style={styles.scrim} onPress={onContinue} />
      <View style={[styles.dock, { paddingBottom: Math.max(insets.bottom, 14) + 8 }]} pointerEvents="box-none">
        <Animated.View
          style={[styles.card, animate(reduceMotion, { animationName: RISE, animationDuration: 320, animationTimingFunction: 'ease-out' })]}>
          <CornerDawn />

          {/* One mark per day of the free week, emptying left to right. */}
          <View style={styles.marks} accessibilityElementsHidden importantForAccessibility="no-hide-descendants">
            {trialMarks(daysLeft).map((theirs, day) => (
              <View key={day} style={[styles.mark, theirs ? styles.markLeft : styles.markSpent]} />
            ))}
          </View>

          <View style={styles.eyebrowRow}>
            <FeatureIcon feature={feature} />
            <Text style={styles.eyebrow}>free trial</Text>
          </View>

          <Text style={styles.title} accessibilityRole="header">
            {reminderTitle(feature, daysLeft)}
          </Text>
          <Text style={styles.blurb}>{reminderBlurb(feature, daysLeft)}</Text>

          <View style={styles.rule} />

          <Pressable
            accessibilityRole="button"
            onPress={onSubscribe}
            style={({ pressed }) => [styles.row, pressed && styles.pressed]}>
            <Text style={styles.keep}>{keepLabel()}</Text>
            <Text style={styles.arrow}>→</Text>
          </Pressable>

          <View style={styles.ruleSoft} />

          <Pressable
            accessibilityRole="button"
            onPress={onContinue}
            style={({ pressed }) => [styles.row, pressed && styles.pressed]}>
            <Text style={styles.later}>not now</Text>
          </Pressable>
        </Animated.View>
      </View>
    </Modal>
  );
}

